// Tema 6 · correcciones de las preguntas OFICIALES verificadas contra el temario oficial (LO 4/2000 + Ley 12/2009)
// Auditoría 22/10/2026: respuestas mal marcadas, «Todas / A y B son correctas» con una opción falsa, «INCORRECTA» con dos opciones falsas,
// cifras y órganos alterados, erratas de OCR («del2ito», «acorda1da») y explicaciones con artículos inventados.
// 1) limpia erratas de OCR en enunciado y opciones de TODAS las oficiales del tema;
// 2) aplica las correcciones de la lista F (cada una devuelve [cita literal, nota]);
// 3) a las oficiales sin cita literal en la explicación les pone la frase del temario que contiene la respuesta (si se encuentra con seguridad).
// Uso: node prompts/herramientas/tema6/fix-t6.js [--dry]     (idempotente; comprueba que cada cita es literal)
const fs = require('fs'), path = require('path');
const RAIZ = path.join(__dirname, '..', '..', '..');
const FILE = path.join(RAIZ, 'test-oficial-conocimiento.html');
const TD = path.join(RAIZ, 'prompts', 'temario-limpio', 'tema6');
const DRY = process.argv.includes('--dry');
const raw = f => fs.readFileSync(path.join(TD, f), 'utf8');
const clean = t => t.replace(/=====PAG \d+=====/g, ' ').replace(/-\s*\n\s*/g, '').replace(/\s+/g, ' ');
const LO = clean(raw('lo4.txt')), L12 = clean(raw('l12.txt'));
const nz = t => t.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9ñ]+/g, '');
const LON = nz(LO), L12N = nz(L12);
// etiqueta «art. X.Y de la …» del sitio exacto donde está la cita (mapa posición normalizada → posición en el texto)
const MAPA = T => { let n = '', m = []; for (let i = 0; i < T.length; i++) { const c = nz(T[i]); for (const ch of c) { n += ch; m.push(i); } } return [n, m]; };
const LINEA = t => t.replace(/=====PAG \d+=====/g, ' ').replace(/-\s*\n\s*/g, '');
const LOL = LINEA(raw('lo4.txt')), L12L = LINEA(raw('l12.txt'));
const MLO = MAPA(LOL), ML12 = MAPA(L12L);
const lab = cita => {
  for (const [T, [TN, M], nom] of [[LOL, MLO, 'LO 4/2000'], [L12L, ML12, 'Ley 12/2009']]) {
    const p = TN.indexOf(nz(cita)); if (p < 0) continue;
    const i = M[p]; const antes = T.slice(0, i);
    const a = [...antes.matchAll(/(Artículo (\d+(?: bis| ter| quáter| quinquies| sexies)?)\. |Disposición (adicional|transitoria|final|derogatoria) ([a-zé]+(?: bis)?)\b)/g)].pop();
    if (!a) return nom;
    if (a[3]) return `disposición ${a[3]} ${a[4]} de la ${nom}`;
    const ap = [...T.slice(a.index + a[0].length, i + 2).matchAll(/\n(\d{1,2}(?: bis)?)\. /g)].pop();
    return `art. ${a[2]}${ap ? '.' + ap[1] : ''} de la ${nom}`;
  }
  return null;
};
